CREATE TABLE IF NOT EXISTS sand_iam_auth_challenge (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    identity_id bigint NULL,
    purpose varchar(32) NOT NULL CHECK (purpose IN ('mfa_login', 'webauthn_register', 'webauthn_auth')),
    token_hash char(64) NOT NULL,
    encrypted_challenge text NOT NULL,
    encrypted_user_handle text NULL,
    encryption_version varchar(32) NOT NULL,
    context jsonb NOT NULL DEFAULT '{}'::jsonb,
    expire_time timestamp(0) without time zone NOT NULL,
    consumed_time timestamp(0) without time zone NULL,
    attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 5),
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_auth_challenge_token UNIQUE (token_hash),
    CONSTRAINT ck_sand_iam_auth_challenge_identity CHECK ((purpose = 'webauthn_auth' AND identity_id IS NULL) OR (purpose <> 'webauthn_auth' AND identity_id IS NOT NULL)),
    CONSTRAINT fk_sand_iam_auth_challenge_identity_application FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_auth_challenge_active ON sand_iam_auth_challenge (application_id, purpose, status, expire_time);
CREATE TABLE IF NOT EXISTS sand_iam_webauthn_credential (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    identity_id bigint NOT NULL,
    name varchar(128) NOT NULL,
    credential_id varchar(1400) NOT NULL,
    public_key text NOT NULL,
    user_handle varchar(128) NOT NULL,
    sign_count bigint NOT NULL DEFAULT 0 CHECK (sign_count >= 0),
    last_used_time timestamp(0) without time zone NULL,
    revoked_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_webauthn_credential_application_credential UNIQUE (application_id, credential_id),
    CONSTRAINT fk_sand_iam_webauthn_credential_identity_application FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_webauthn_credential_identity_active ON sand_iam_webauthn_credential (application_id, identity_id, status);
COMMIT;

-- lifecycle source: migrations/005_oauth_oidc.pgsql
-- IAM-T03-005 BEGIN
-- OAuth 2.0 / OpenID Connect provider records.  All user and client records
-- are application scoped; signing-key history is issuer scoped by design.
BEGIN;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_sand_iam_auth_session_id_application_identity') THEN ALTER TABLE sand_iam_auth_session ADD CONSTRAINT uk_sand_iam_auth_session_id_application_identity UNIQUE (id, application_id, identity_id); END IF; END $$;

CREATE TABLE IF NOT EXISTS sand_iam_oauth_client (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    code varchar(128) NOT NULL,
    name varchar(128) NOT NULL,
    client_type varchar(16) NOT NULL CHECK (client_type IN ('public', 'confidential')),
    secret_hash varchar(255) NULL,
    secret_version varchar(32) NULL,
    redirect_uris jsonb NOT NULL DEFAULT '[]'::jsonb,
    post_logout_redirect_uris jsonb NOT NULL DEFAULT '[]'::jsonb,
    allowed_scopes jsonb NOT NULL DEFAULT '["openid","profile","email"]'::jsonb,
    allowed_audiences jsonb NOT NULL DEFAULT '[]'::jsonb,
    default_audience varchar(255) NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    -- client_id is presented at issuer-wide endpoints, so it cannot be scoped
    -- only to an application even though all ownership FKs remain scoped.
    CONSTRAINT uk_sand_iam_oauth_client_code UNIQUE (code),
    CONSTRAINT uk_sand_iam_oauth_client_id_application UNIQUE (id, application_id),
    CONSTRAINT ck_sand_iam_oauth_client_secret CHECK ((client_type = 'public' AND secret_hash IS NULL AND secret_version IS NULL) OR (client_type = 'confidential' AND secret_hash IS NOT NULL AND secret_version IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_client_application_active ON sand_iam_oauth_client (application_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_oauth_consent (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    client_id bigint NOT NULL,
    identity_id bigint NOT NULL,
    scope varchar(1000) NOT NULL,
    granted_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_oauth_consent_scope UNIQUE (application_id, client_id, identity_id),
    CONSTRAINT fk_sand_iam_oauth_consent_client_scope FOREIGN KEY (client_id, application_id) REFERENCES sand_iam_oauth_client(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_consent_identity_scope FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_consent_identity_active ON sand_iam_oauth_consent (application_id, identity_id, status);

-- Browser authorization requests are server-side, one-time records.  The
-- browser only carries an opaque request handle and a same-site CSRF proof;
-- state, nonce and PKCE data are encrypted inside this record.
CREATE TABLE IF NOT EXISTS sand_iam_oauth_authorization_request (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    client_id bigint NOT NULL,
    identity_id bigint NULL,
    auth_session_id bigint NULL,
    -- session and identity are intentionally bound only by POST interaction/session.
    request_hash char(64) NOT NULL,
    csrf_hash char(64) NOT NULL,
    encrypted_payload text NOT NULL,
    encryption_version varchar(32) NOT NULL,
    expire_time timestamp(0) without time zone NOT NULL,
    consumed_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_oauth_authorization_request_hash UNIQUE (request_hash),
    CONSTRAINT ck_sand_iam_oauth_authorization_request_binding CHECK ((identity_id IS NULL AND auth_session_id IS NULL) OR (identity_id IS NOT NULL AND auth_session_id IS NOT NULL)),
    CONSTRAINT fk_sand_iam_oauth_authorization_request_client_scope FOREIGN KEY (client_id, application_id) REFERENCES sand_iam_oauth_client(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_authorization_request_identity_scope FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_authorization_request_session_scope FOREIGN KEY (auth_session_id, application_id, identity_id) REFERENCES sand_iam_auth_session(id, application_id, identity_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_authorization_request_active ON sand_iam_oauth_authorization_request (application_id, client_id, identity_id, status, expire_time);

CREATE TABLE IF NOT EXISTS sand_iam_oauth_grant (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    client_id bigint NOT NULL,
    identity_id bigint NULL,
    auth_session_id bigint NULL,
    grant_type varchar(24) NOT NULL CHECK (grant_type IN ('authorization_code', 'client_credentials')),
    scope varchar(1000) NOT NULL,
    auth_time timestamp(0) without time zone NULL,
    revoked_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_oauth_grant_id_application UNIQUE (id, application_id),
    CONSTRAINT uk_sand_iam_oauth_grant_id_application_client UNIQUE (id, application_id, client_id),
    CONSTRAINT ck_sand_iam_oauth_grant_subject CHECK ((grant_type = 'authorization_code' AND identity_id IS NOT NULL AND auth_session_id IS NOT NULL AND auth_time IS NOT NULL) OR (grant_type = 'client_credentials' AND identity_id IS NULL AND auth_session_id IS NULL AND auth_time IS NULL)),
    CONSTRAINT fk_sand_iam_oauth_grant_client_scope FOREIGN KEY (client_id, application_id) REFERENCES sand_iam_oauth_client(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_grant_identity_scope FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_grant_session_scope FOREIGN KEY (auth_session_id, application_id, identity_id) REFERENCES sand_iam_auth_session(id, application_id, identity_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_grant_active ON sand_iam_oauth_grant (application_id, client_id, identity_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_authorization_code (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    client_id bigint NOT NULL,
    identity_id bigint NOT NULL,
    auth_session_id bigint NOT NULL,
    code_hash char(64) NOT NULL,
    redirect_uri varchar(2048) NOT NULL,
    scope varchar(1000) NOT NULL,
    encrypted_nonce text NULL,
    nonce_encryption_version varchar(32) NULL,
    nonce_hash char(64) NULL,
    code_challenge varchar(128) NOT NULL,
    code_challenge_method varchar(8) NOT NULL CHECK (code_challenge_method = 'S256'),
    auth_time timestamp(0) without time zone NOT NULL,
    expire_time timestamp(0) without time zone NOT NULL,
    consumed_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_authorization_code_hash UNIQUE (code_hash),
    CONSTRAINT fk_sand_iam_authorization_code_client_scope FOREIGN KEY (client_id, application_id) REFERENCES sand_iam_oauth_client(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_authorization_code_identity_scope FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_authorization_code_session_scope FOREIGN KEY (auth_session_id, application_id, identity_id) REFERENCES sand_iam_auth_session(id, application_id, identity_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_authorization_code_active ON sand_iam_authorization_code (application_id, client_id, status, expire_time);

CREATE TABLE IF NOT EXISTS sand_iam_oauth_token (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    client_id bigint NOT NULL,
    grant_id bigint NOT NULL,
    identity_id bigint NULL,
    token_type varchar(16) NOT NULL CHECK (token_type IN ('access', 'refresh', 'id')),
    token_hash char(64) NOT NULL,
    token_id varchar(96) NOT NULL,
    scope varchar(1000) NOT NULL,
    expire_time timestamp(0) without time zone NOT NULL,
    used_time timestamp(0) without time zone NULL,
    revoked_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_oauth_token_hash UNIQUE (token_hash),
    CONSTRAINT uk_sand_iam_oauth_token_id UNIQUE (token_id),
    CONSTRAINT fk_sand_iam_oauth_token_client_scope FOREIGN KEY (client_id, application_id) REFERENCES sand_iam_oauth_client(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_token_grant_scope FOREIGN KEY (grant_id, application_id, client_id) REFERENCES sand_iam_oauth_grant(id, application_id, client_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oauth_token_identity_scope FOREIGN KEY (identity_id, application_id) REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_token_grant_active ON sand_iam_oauth_token (application_id, grant_id, token_type, status, expire_time);

CREATE TABLE IF NOT EXISTS sand_iam_oidc_signing_key (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kid varchar(128) NOT NULL,
    public_jwk jsonb NOT NULL,
    -- Private material is write-only. Imported verification keys intentionally
    -- have no private material, so the two envelope fields stay nullable as a pair.
    encrypted_private_key text NULL,
    encryption_version varchar(32) NULL,
    algorithm varchar(16) NOT NULL DEFAULT 'RS256',
    state varchar(16) NOT NULL CHECK (state IN ('active', 'verify_only', 'retired')),
    not_before_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    retire_time timestamp(0) without time zone NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_oidc_signing_key_kid UNIQUE (kid)
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_oidc_signing_key_publish ON sand_iam_oidc_signing_key (state, retire_time);
COMMENT ON COLUMN sand_iam_oidc_signing_key.encrypted_private_key IS 'Write-only versioned private-key envelope; NULL only when no private signing material is stored.';
COMMENT ON COLUMN sand_iam_oidc_signing_key.encryption_version IS 'Key-encryption version for encrypted_private_key; NULL when no private signing material is stored.';

COMMIT;
-- IAM-T03-005 END

-- lifecycle source: migrations/006_federation_directory_scim.pgsql
-- IAM-T04-006 BEGIN: application-scoped federation, directory and SCIM.
-- Secrets stay in encrypted_config/token_hash.  Raw directory credentials,
-- bearer tokens and assertion payloads are never persisted.

ALTER TABLE sand_iam_identity_provider
    ADD COLUMN IF NOT EXISTS scope_type varchar(16) NOT NULL DEFAULT 'application',
    ADD COLUMN IF NOT EXISTS organization_id bigint NULL,
    ADD COLUMN IF NOT EXISTS public_code varchar(64) NOT NULL DEFAULT ('ip_' || md5(random()::text || clock_timestamp()::text)),
    ADD COLUMN IF NOT EXISTS provider_type varchar(16) NOT NULL DEFAULT 'local',
    ADD COLUMN IF NOT EXISTS encrypted_config text NULL,
    ADD COLUMN IF NOT EXISTS attribute_mapping jsonb NOT NULL DEFAULT '{}'::jsonb,
    ADD COLUMN IF NOT EXISTS conflict_policy varchar(16) NOT NULL DEFAULT 'reject',
    ADD COLUMN IF NOT EXISTS sync_cursor varchar(512) NULL,
    ADD COLUMN IF NOT EXISTS last_sync_time timestamp(0) without time zone NULL;

UPDATE sand_iam_identity_provider provider
SET organization_id = application.organization_id
FROM sand_iam_application application
WHERE provider.application_id = application.id AND provider.organization_id IS NULL;

ALTER TABLE sand_iam_identity_provider
    ALTER COLUMN organization_id SET NOT NULL,
    ALTER COLUMN application_id DROP NOT NULL,
    DROP CONSTRAINT IF EXISTS ck_sand_iam_identity_provider_type,
    DROP CONSTRAINT IF EXISTS ck_sand_iam_identity_provider_conflict_policy,
    DROP CONSTRAINT IF EXISTS ck_sand_iam_identity_provider_scope;
ALTER TABLE sand_iam_identity_provider
    ADD CONSTRAINT ck_sand_iam_identity_provider_type CHECK (provider_type IN ('local', 'oidc', 'oauth2', 'saml', 'ldap', 'scim', 'kerberos')),
    ADD CONSTRAINT ck_sand_iam_identity_provider_conflict_policy CHECK (conflict_policy IN ('reject', 'link_verified', 'create')),
    ADD CONSTRAINT ck_sand_iam_identity_provider_scope CHECK ((scope_type = 'application' AND application_id IS NOT NULL) OR (scope_type = 'organization' AND application_id IS NULL));
DO $$ BEGIN ALTER TABLE sand_iam_identity_provider ADD CONSTRAINT uk_sand_iam_identity_provider_public_code UNIQUE (public_code); EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE sand_iam_identity_provider ADD CONSTRAINT fk_sand_iam_identity_provider_organization FOREIGN KEY (organization_id) REFERENCES sand_iam_organization(id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;
ALTER TABLE sand_iam_identity_provider
    ADD COLUMN IF NOT EXISTS scope_application_key bigint GENERATED ALWAYS AS (COALESCE(application_id, 0)) STORED;
DO $$ BEGIN ALTER TABLE sand_iam_application ADD CONSTRAINT uk_sand_iam_application_id_organization UNIQUE (id, organization_id); EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE sand_iam_identity_provider ADD CONSTRAINT uk_sand_iam_identity_provider_scope_key UNIQUE (id, organization_id, scope_application_key); EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE sand_iam_identity_provider ADD CONSTRAINT fk_sand_iam_identity_provider_application_organization FOREIGN KEY (application_id, organization_id) REFERENCES sand_iam_application(id, organization_id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;
CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_provider_type_status ON sand_iam_identity_provider (organization_id, provider_type, status);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_identity_provider_organization_code ON sand_iam_identity_provider (organization_id, code) WHERE scope_type = 'organization';

CREATE TABLE IF NOT EXISTS sand_iam_identity_provider_application (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identity_provider_id bigint NOT NULL,
    application_id bigint NOT NULL,
    organization_id bigint NOT NULL,
    provider_scope_application_key bigint NOT NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_identity_provider_application UNIQUE (identity_provider_id, application_id),
    CONSTRAINT ck_sand_iam_identity_provider_application_scope CHECK (provider_scope_application_key = 0 OR provider_scope_application_key = application_id),
    CONSTRAINT fk_sand_iam_identity_provider_application_provider FOREIGN KEY (identity_provider_id, organization_id, provider_scope_application_key) REFERENCES sand_iam_identity_provider(id, organization_id, scope_application_key) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_identity_provider_application_application FOREIGN KEY (application_id, organization_id) REFERENCES sand_iam_application(id, organization_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_provider_application_application ON sand_iam_identity_provider_application (application_id, status);
INSERT INTO sand_iam_identity_provider_application (identity_provider_id, application_id, organization_id, provider_scope_application_key, status)
SELECT id, application_id, organization_id, scope_application_key, status FROM sand_iam_identity_provider WHERE application_id IS NOT NULL
ON CONFLICT (identity_provider_id, application_id) DO NOTHING;

ALTER TABLE sand_iam_identity_binding
    DROP CONSTRAINT IF EXISTS fk_sand_iam_identity_binding_provider_application,
    DROP CONSTRAINT IF EXISTS uk_sand_iam_identity_binding_provider_subject,
    DROP CONSTRAINT IF EXISTS uk_sand_iam_identity_binding_provider_application_subject;
ALTER TABLE sand_iam_identity_binding
    ADD CONSTRAINT fk_sand_iam_identity_binding_provider_application FOREIGN KEY (identity_provider_id, application_id) REFERENCES sand_iam_identity_provider_application(identity_provider_id, application_id) ON DELETE RESTRICT,
    ADD CONSTRAINT uk_sand_iam_identity_binding_provider_application_subject UNIQUE (identity_provider_id, application_id, subject);

CREATE TABLE IF NOT EXISTS sand_iam_federation_transaction (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL,
    identity_provider_id bigint NOT NULL,
    protocol varchar(16) NOT NULL CHECK (protocol IN ('oidc', 'saml')),
    purpose varchar(16) NOT NULL DEFAULT 'login' CHECK (purpose IN ('login', 'link')),
    state_hash char(64) NOT NULL,
    browser_binding_hash char(64) NULL,
    saml_request_id varchar(191) NULL,
    nonce_hash char(64) NULL,
    assertion_hash char(64) NULL,
    encrypted_pkce_verifier text NULL,
    redirect_uri varchar(2048) NULL,
    expire_time timestamp(0) without time zone NOT NULL,
    consumed_time timestamp(0) without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_federation_transaction_state UNIQUE (state_hash),
    CONSTRAINT fk_sand_iam_federation_transaction_provider_application FOREIGN KEY (identity_provider_id, application_id) REFERENCES sand_iam_identity_provider_application(identity_provider_id, application_id) ON DELETE RESTRICT
);
ALTER TABLE sand_iam_federation_transaction ADD COLUMN IF NOT EXISTS assertion_hash char(64) NULL;
ALTER TABLE sand_iam_federation_transaction ADD COLUMN IF NOT EXISTS purpose varchar(16) NOT NULL DEFAULT 'login';
ALTER TABLE sand_iam_federation_transaction ADD COLUMN IF NOT EXISTS browser_binding_hash char(64) NULL;
ALTER TABLE sand_iam_federation_transaction ADD COLUMN IF NOT EXISTS saml_request_id varchar(191) NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_federation_transaction_assertion ON sand_iam_federation_transaction (identity_provider_id, application_id, assertion_hash) WHERE assertion_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_sand_iam_federation_transaction_provider_expire ON sand_iam_federation_transaction (identity_provider_id, expire_time);

ALTER TABLE sand_iam_auth_session
    ADD COLUMN IF NOT EXISTS auth_method varchar(32) NOT NULL DEFAULT 'local_password',
    ADD COLUMN IF NOT EXISTS identity_binding_id bigint NULL;
ALTER TABLE sand_iam_auth_session DROP CONSTRAINT IF EXISTS ck_sand_iam_auth_session_auth_method;
ALTER TABLE sand_iam_auth_session ADD CONSTRAINT ck_sand_iam_auth_session_auth_method CHECK (auth_method IN ('local_password', 'federation'));
DO $$ BEGIN ALTER TABLE sand_iam_auth_session ADD CONSTRAINT fk_sand_iam_auth_session_identity_binding FOREIGN KEY (identity_binding_id) REFERENCES sand_iam_identity_binding(id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE INDEX IF NOT EXISTS idx_sand_iam_auth_session_binding_active ON sand_iam_auth_session (identity_binding_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_directory_sync_run (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL,
    identity_provider_id bigint NOT NULL,
    state varchar(16) NOT NULL CHECK (state IN ('running', 'succeeded', 'failed', 'partial')),
    cursor_before varchar(512) NULL,
    cursor_after varchar(512) NULL,
    processed_count integer NOT NULL DEFAULT 0 CHECK (processed_count >= 0),
    failed_count integer NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    error_code varchar(96) NULL,
    start_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finish_time timestamp(0) without time zone NULL,
    CONSTRAINT fk_sand_iam_directory_sync_run_provider_application FOREIGN KEY (identity_provider_id, application_id) REFERENCES sand_iam_identity_provider_application(identity_provider_id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_directory_sync_run_provider_start ON sand_iam_directory_sync_run (identity_provider_id, start_time DESC);

CREATE TABLE IF NOT EXISTS sand_iam_scim_token (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL,
    identity_provider_id bigint NOT NULL,
    name varchar(128) NOT NULL,
    token_hash char(64) NOT NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    expire_time timestamp(0) without time zone NULL,
    last_used_time timestamp(0) without time zone NULL,
    created_by bigint NULL,
    updated_by bigint NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_scim_token_hash UNIQUE (token_hash),
    CONSTRAINT uk_sand_iam_scim_token_provider_name UNIQUE (identity_provider_id, name),
    CONSTRAINT fk_sand_iam_scim_token_provider_application FOREIGN KEY (identity_provider_id, application_id) REFERENCES sand_iam_identity_provider_application(identity_provider_id, application_id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_scim_token_provider_status ON sand_iam_scim_token (identity_provider_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_scim_group (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL,
    identity_provider_id bigint NOT NULL,
    external_id varchar(191) NOT NULL,
    display_name varchar(256) NOT NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_scim_group_provider_external UNIQUE (identity_provider_id, application_id, external_id),
