-- lifecycle source: migrations/012_identity_lifecycle_group.pgsql
-- SandIAM T10 phase 1: identity lifecycle and application-local groups.
-- PostgreSQL only; integrated into the generated root lifecycle.

ALTER TABLE sand_iam_identity
    ADD COLUMN IF NOT EXISTS lifecycle_state VARCHAR(16) NOT NULL DEFAULT 'active',
    ADD COLUMN IF NOT EXISTS state_before_delete VARCHAR(16),
    ADD COLUMN IF NOT EXISTS deleted_time TIMESTAMP WITHOUT TIME ZONE,
    ADD COLUMN IF NOT EXISTS purge_after TIMESTAMP WITHOUT TIME ZONE,
    ADD COLUMN IF NOT EXISTS external_guest_ref_hash CHAR(64);

UPDATE sand_iam_identity
SET lifecycle_state = CASE WHEN status = 1 THEN 'active' ELSE 'disabled' END
WHERE lifecycle_state = 'active' AND status <> 1;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_identity_lifecycle_state') THEN ALTER TABLE sand_iam_identity ADD CONSTRAINT ck_sand_iam_identity_lifecycle_state CHECK (lifecycle_state IN ('pending', 'active', 'disabled', 'guest', 'deleted')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_identity_state_before_delete') THEN ALTER TABLE sand_iam_identity ADD CONSTRAINT ck_sand_iam_identity_state_before_delete CHECK (state_before_delete IS NULL OR state_before_delete IN ('pending', 'active', 'disabled', 'guest')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_sand_iam_identity_id_application') THEN ALTER TABLE sand_iam_identity ADD CONSTRAINT uk_sand_iam_identity_id_application UNIQUE (id, application_id); END IF; END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_identity_guest_application
    ON sand_iam_identity(application_id, external_guest_ref_hash)
    WHERE external_guest_ref_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_application_lifecycle
    ON sand_iam_identity(application_id, lifecycle_state, status);
CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_purge_after
    ON sand_iam_identity(purge_after)
    WHERE lifecycle_state = 'deleted';

CREATE TABLE IF NOT EXISTS sand_iam_identity_group (
    id BIGSERIAL PRIMARY KEY,
    application_id BIGINT NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    parent_id BIGINT,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    description VARCHAR(500),
    depth SMALLINT NOT NULL DEFAULT 1 CHECK (depth BETWEEN 1 AND 8),
    status SMALLINT NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_identity_group_app_code UNIQUE (application_id, code),
    CONSTRAINT uk_sand_iam_identity_group_id_app UNIQUE (id, application_id),
    CONSTRAINT fk_sand_iam_identity_group_parent_app FOREIGN KEY (parent_id, application_id)
        REFERENCES sand_iam_identity_group(id, application_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_group_parent
    ON sand_iam_identity_group(application_id, parent_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_identity_group_member (
    id BIGSERIAL PRIMARY KEY,
    identity_group_id BIGINT NOT NULL,
    application_id BIGINT NOT NULL,
    identity_id BIGINT NOT NULL,
    status SMALLINT NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_identity_group_member UNIQUE (identity_group_id, identity_id),
    CONSTRAINT fk_sand_iam_group_member_group_app FOREIGN KEY (identity_group_id, application_id)
        REFERENCES sand_iam_identity_group(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_group_member_identity_app FOREIGN KEY (identity_id, application_id)
        REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_group_member_identity
    ON sand_iam_identity_group_member(application_id, identity_id, status);

INSERT INTO sand_iam_service (code, name, status)
VALUES ('sand-iam', 'SandIAM 身份服务', 1)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

INSERT INTO sand_iam_service_action (service_id, code, name, status)
SELECT id, 'identity.guest.upsert', '创建或更新应用访客', 1
FROM sand_iam_service WHERE code = 'sand-iam'
ON CONFLICT (service_id, code) DO UPDATE SET name = EXCLUDED.name;

-- lifecycle source: migrations/013_identity_invitation.pgsql
-- SandIAM T10 phase 2: application invitation lifecycle.
-- PostgreSQL only; integrated into the generated root lifecycle.

CREATE TABLE IF NOT EXISTS sand_iam_identity_invitation (
    id BIGSERIAL PRIMARY KEY,
    application_id BIGINT NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    target_type VARCHAR(16) NOT NULL CHECK (target_type IN ('email', 'phone')),
    target_hash CHAR(64) NOT NULL,
    target_masked VARCHAR(320) NOT NULL,
    encrypted_target TEXT,
    token_hash CHAR(64) NOT NULL,
    encrypted_delivery_token TEXT,
    initial_group_ids JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(initial_group_ids) = 'array'),
    invited_by VARCHAR(64) NOT NULL,
    state VARCHAR(24) NOT NULL CHECK (state IN ('sending', 'pending', 'delivery_failed', 'accepted', 'revoked', 'expired')),
    identity_id BIGINT,
    guest_identity_id BIGINT,
    expire_time TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    delivered_time TIMESTAMP WITHOUT TIME ZONE,
    consumed_time TIMESTAMP WITHOUT TIME ZONE,
    delivery_error_code VARCHAR(128),
    status SMALLINT NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_invitation_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_sand_iam_invitation_identity_app FOREIGN KEY (identity_id, application_id)
        REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_invitation_guest_identity_app FOREIGN KEY (guest_identity_id, application_id)
        REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_invitation_active_target
    ON sand_iam_identity_invitation(application_id, target_hash)
    WHERE state IN ('sending', 'pending', 'delivery_failed');
CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_invitation_active_guest
    ON sand_iam_identity_invitation(application_id, guest_identity_id)
    WHERE guest_identity_id IS NOT NULL AND state IN ('sending', 'pending', 'delivery_failed');
CREATE INDEX IF NOT EXISTS idx_sand_iam_invitation_application_state
    ON sand_iam_identity_invitation(application_id, state, expire_time);

-- lifecycle source: migrations/014_identity_import_export.pgsql
-- SandIAM T10 phase 4: two-step identity CSV import and export reports.
-- PostgreSQL only; integrated into the generated root lifecycle.

CREATE TABLE IF NOT EXISTS sand_iam_identity_import_job (
    id BIGSERIAL PRIMARY KEY,
    application_id BIGINT NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    original_name VARCHAR(255) NOT NULL,
    content_digest CHAR(64) NOT NULL,
    mode VARCHAR(16) NOT NULL CHECK (mode IN ('create', 'update')),
    state VARCHAR(16) NOT NULL CHECK (state IN ('previewed', 'running', 'completed', 'partial', 'failed')),
    total_count INTEGER NOT NULL DEFAULT 0 CHECK (total_count >= 0),
    valid_count INTEGER NOT NULL DEFAULT 0 CHECK (valid_count >= 0),
    invalid_count INTEGER NOT NULL DEFAULT 0 CHECK (invalid_count >= 0),
    success_count INTEGER NOT NULL DEFAULT 0 CHECK (success_count >= 0),
    warning_count INTEGER NOT NULL DEFAULT 0 CHECK (warning_count >= 0),
    failure_count INTEGER NOT NULL DEFAULT 0 CHECK (failure_count >= 0),
    created_by VARCHAR(64) NOT NULL,
    confirmed_time TIMESTAMP WITHOUT TIME ZONE,
    completed_time TIMESTAMP WITHOUT TIME ZONE,
    status SMALLINT NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_import_job_application_state
    ON sand_iam_identity_import_job(application_id, state, id DESC);

CREATE TABLE IF NOT EXISTS sand_iam_identity_import_row (
    id BIGSERIAL PRIMARY KEY,
    import_job_id BIGINT NOT NULL REFERENCES sand_iam_identity_import_job(id) ON DELETE RESTRICT,
    application_id BIGINT NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    row_number INTEGER NOT NULL CHECK (row_number >= 2),
    idempotency_key CHAR(64) NOT NULL,
    encrypted_payload TEXT,
    summary JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(summary) = 'object'),
    validation_errors JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(validation_errors) = 'array'),
    state VARCHAR(32) NOT NULL CHECK (state IN ('valid', 'invalid', 'processing', 'succeeded', 'succeeded_with_warning', 'failed')),
    result_identity_id BIGINT,
    result_invitation_id BIGINT,
    error_code VARCHAR(128),
    status SMALLINT NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_import_row_job_number UNIQUE (import_job_id, row_number),
    CONSTRAINT uk_sand_iam_import_row_idempotency UNIQUE (idempotency_key),
    CONSTRAINT fk_sand_iam_import_row_identity_app FOREIGN KEY (result_identity_id, application_id)
        REFERENCES sand_iam_identity(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_import_row_invitation FOREIGN KEY (result_invitation_id)
        REFERENCES sand_iam_identity_invitation(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_sand_iam_import_row_job_state
    ON sand_iam_identity_import_row(import_job_id, state, row_number);

-- lifecycle source: migrations/015_identity_sync_connector.pgsql
-- SandIAM T10: application-scoped identity synchronization connector.
-- Candidate migration only. The root install/update/uninstall lifecycle scripts
-- remain the release source of truth and must be integrated and verified separately.

CREATE TABLE IF NOT EXISTS sand_iam_sync_connector (
    id BIGSERIAL PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    application_id BIGINT NOT NULL,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    direction VARCHAR(16) NOT NULL DEFAULT 'inbound',
    driver_code VARCHAR(64) NOT NULL,
    encrypted_config TEXT NULL,
    config_version INTEGER NOT NULL DEFAULT 0,
    authority_map JSONB NOT NULL DEFAULT '{}'::JSONB,
    conflict_policy VARCHAR(16) NOT NULL DEFAULT 'manual',
    encrypted_cursor TEXT NULL,
    missing_protection_hours INTEGER NOT NULL DEFAULT 24,
    disable_threshold_percent INTEGER NOT NULL DEFAULT 20,
    last_sync_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_sync_connector_direction
        CHECK (direction IN ('inbound', 'outbound', 'bidirectional')),
    CONSTRAINT ck_sand_iam_sync_connector_conflict_policy
        CHECK (conflict_policy IN ('manual', 'reject', 'source_wins', 'local_wins')),
    CONSTRAINT ck_sand_iam_sync_connector_config_version
        CHECK (config_version >= 0),
    CONSTRAINT ck_sand_iam_sync_connector_missing_protection
        CHECK (missing_protection_hours BETWEEN 1 AND 720),
    CONSTRAINT ck_sand_iam_sync_connector_disable_threshold
        CHECK (disable_threshold_percent BETWEEN 1 AND 100),
    CONSTRAINT ck_sand_iam_sync_connector_status
        CHECK (status IN (1, 2)),
    CONSTRAINT uk_sand_iam_sync_connector_app_code
        UNIQUE (application_id, code),
    CONSTRAINT uk_sand_iam_sync_connector_id_app
        UNIQUE (id, application_id),
    CONSTRAINT fk_sand_iam_sync_connector_org
        FOREIGN KEY (organization_id) REFERENCES sand_iam_organization (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_sync_connector_app
        FOREIGN KEY (application_id) REFERENCES sand_iam_application (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_sync_connector_app_status
    ON sand_iam_sync_connector (application_id, status, id DESC);

CREATE TABLE IF NOT EXISTS sand_iam_sync_run (
    id BIGSERIAL PRIMARY KEY,
    sync_connector_id BIGINT NOT NULL,
    application_id BIGINT NOT NULL,
    connector_config_version INTEGER NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'running',
    cursor_before_hash CHAR(64) NULL,
    cursor_after_hash CHAR(64) NULL,
    pulled INTEGER NOT NULL DEFAULT 0,
    pushed INTEGER NOT NULL DEFAULT 0,
    created INTEGER NOT NULL DEFAULT 0,
    updated INTEGER NOT NULL DEFAULT 0,
    missing INTEGER NOT NULL DEFAULT 0,
    disabled INTEGER NOT NULL DEFAULT 0,
    conflict INTEGER NOT NULL DEFAULT 0,
    error_code VARCHAR(128) NULL,
    start_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    finish_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_sync_run_state
        CHECK (state IN ('running', 'succeeded', 'failed')),
    CONSTRAINT ck_sand_iam_sync_run_counts
        CHECK (pulled >= 0 AND pushed >= 0 AND created >= 0 AND updated >= 0
            AND missing >= 0 AND disabled >= 0 AND conflict >= 0),
    CONSTRAINT ck_sand_iam_sync_run_status
        CHECK (status IN (1, 2)),
    CONSTRAINT uk_sand_iam_sync_run_id_app
        UNIQUE (id, application_id),
    CONSTRAINT fk_sand_iam_sync_run_connector_app
        FOREIGN KEY (sync_connector_id, application_id)
        REFERENCES sand_iam_sync_connector (id, application_id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_sync_run_running
    ON sand_iam_sync_run (sync_connector_id)
    WHERE state = 'running';
CREATE INDEX IF NOT EXISTS idx_sand_iam_sync_run_connector_time
    ON sand_iam_sync_run (sync_connector_id, id DESC);

CREATE TABLE IF NOT EXISTS sand_iam_sync_resource (
    id BIGSERIAL PRIMARY KEY,
    sync_connector_id BIGINT NOT NULL,
    application_id BIGINT NOT NULL,
    source_key_hash CHAR(64) NOT NULL,
    source_version VARCHAR(128) NOT NULL,
    identity_id BIGINT NOT NULL,
    encrypted_snapshot TEXT NOT NULL,
    snapshot_hash CHAR(64) NOT NULL,
    source_state VARCHAR(16) NOT NULL DEFAULT 'active',
    missing_since TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    last_seen_run_id BIGINT NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_sync_resource_state
        CHECK (source_state IN ('active', 'missing', 'disabled', 'conflict')),
    CONSTRAINT ck_sand_iam_sync_resource_status
        CHECK (status IN (1, 2)),
    CONSTRAINT uk_sand_iam_sync_resource_source
        UNIQUE (sync_connector_id, source_key_hash),
    CONSTRAINT fk_sand_iam_sync_resource_connector_app
        FOREIGN KEY (sync_connector_id, application_id)
        REFERENCES sand_iam_sync_connector (id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_sync_resource_identity_app
        FOREIGN KEY (identity_id, application_id)
        REFERENCES sand_iam_identity (id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_sync_resource_run_app
        FOREIGN KEY (last_seen_run_id, application_id)
        REFERENCES sand_iam_sync_run (id, application_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_sync_resource_missing
    ON sand_iam_sync_resource (sync_connector_id, missing_since)
    WHERE source_state = 'missing' AND status = 1;
CREATE INDEX IF NOT EXISTS idx_sand_iam_sync_resource_identity
    ON sand_iam_sync_resource (application_id, identity_id);

CREATE TABLE IF NOT EXISTS sand_iam_sync_outbox (
    id BIGSERIAL PRIMARY KEY,
    sync_connector_id BIGINT NOT NULL,
    application_id BIGINT NOT NULL,
    identity_id BIGINT NOT NULL,
    event_id VARCHAR(128) NOT NULL,
    operation VARCHAR(16) NOT NULL,
    encrypted_payload TEXT NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    error_code VARCHAR(128) NULL,
    delivered_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_sync_outbox_operation
        CHECK (operation IN ('create', 'update', 'disable', 'delete')),
    CONSTRAINT ck_sand_iam_sync_outbox_state
        CHECK (state IN ('pending', 'succeeded', 'failed')),
    CONSTRAINT ck_sand_iam_sync_outbox_attempt_count
        CHECK (attempt_count >= 0),
    CONSTRAINT ck_sand_iam_sync_outbox_status
        CHECK (status IN (1, 2)),
    CONSTRAINT uk_sand_iam_sync_outbox_event
        UNIQUE (event_id),
    CONSTRAINT fk_sand_iam_sync_outbox_connector_app
        FOREIGN KEY (sync_connector_id, application_id)
        REFERENCES sand_iam_sync_connector (id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_sync_outbox_identity_app
        FOREIGN KEY (identity_id, application_id)
        REFERENCES sand_iam_identity (id, application_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_sync_outbox_pending
    ON sand_iam_sync_outbox (sync_connector_id, id)
    WHERE state = 'pending' AND status = 1;

-- lifecycle source: migrations/016_oauth_dynamic_registration_logout.pgsql
-- SandIAM T11: RFC 7591 initial access tokens and OIDC logout metadata.
-- Candidate migration only; root lifecycle integration is verified separately.

CREATE TABLE IF NOT EXISTS sand_iam_oauth_registration_token (
    id BIGSERIAL PRIMARY KEY,
    application_id BIGINT NOT NULL,
    name VARCHAR(128) NOT NULL,
    token_hash CHAR(64) NOT NULL,
    allowed_redirect_hosts JSONB NOT NULL DEFAULT '[]'::JSONB,
    allowed_scopes JSONB NOT NULL DEFAULT '[]'::JSONB,
    max_uses INTEGER NOT NULL DEFAULT 1,
    used_count INTEGER NOT NULL DEFAULT 0,
    expire_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL,
    issued_by VARCHAR(128) NOT NULL,
    last_used_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    last_used_ip_hash CHAR(64) NULL,
    revoked_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_oauth_registration_token_hash UNIQUE (token_hash),
    CONSTRAINT ck_sand_iam_oauth_registration_token_hosts CHECK (jsonb_typeof(allowed_redirect_hosts) = 'array'),
    CONSTRAINT ck_sand_iam_oauth_registration_token_scopes CHECK (jsonb_typeof(allowed_scopes) = 'array'),
    CONSTRAINT ck_sand_iam_oauth_registration_token_uses CHECK (max_uses BETWEEN 1 AND 1000 AND used_count BETWEEN 0 AND max_uses),
    CONSTRAINT ck_sand_iam_oauth_registration_token_status CHECK (status IN (1, 2)),
    CONSTRAINT fk_sand_iam_oauth_registration_token_app FOREIGN KEY (application_id) REFERENCES sand_iam_application (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_registration_token_app_status
    ON sand_iam_oauth_registration_token (application_id, status, expire_time, id DESC);

ALTER TABLE sand_iam_oauth_client
    ADD COLUMN IF NOT EXISTS registration_source VARCHAR(16) NOT NULL DEFAULT 'manual',
    ADD COLUMN IF NOT EXISTS dynamic_registration_token_id BIGINT NULL,
    ADD COLUMN IF NOT EXISTS frontchannel_logout_uri VARCHAR(2048) NULL,
    ADD COLUMN IF NOT EXISTS frontchannel_logout_session_required BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN IF NOT EXISTS backchannel_logout_uri VARCHAR(2048) NULL,
    ADD COLUMN IF NOT EXISTS backchannel_logout_session_required BOOLEAN NOT NULL DEFAULT TRUE;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_oauth_client_registration_source') THEN ALTER TABLE sand_iam_oauth_client ADD CONSTRAINT ck_sand_iam_oauth_client_registration_source CHECK (registration_source IN ('manual', 'dynamic')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_sand_iam_oauth_client_dcr_token') THEN ALTER TABLE sand_iam_oauth_client ADD CONSTRAINT fk_sand_iam_oauth_client_dcr_token FOREIGN KEY (dynamic_registration_token_id) REFERENCES sand_iam_oauth_registration_token (id) ON DELETE RESTRICT; END IF; END $$;

CREATE INDEX IF NOT EXISTS idx_sand_iam_oauth_client_dcr_token
    ON sand_iam_oauth_client (dynamic_registration_token_id)
    WHERE dynamic_registration_token_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS sand_iam_oidc_logout_delivery (
    id BIGSERIAL PRIMARY KEY,
    application_id BIGINT NOT NULL,
    oauth_client_id BIGINT NOT NULL,
    auth_session_id BIGINT NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    encrypted_logout_token TEXT NOT NULL,
    state VARCHAR(16) NOT NULL DEFAULT 'pending',
    attempt_count INTEGER NOT NULL DEFAULT 0,
    next_attempt_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    locked_until TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    delivered_time TIMESTAMP(0) WITHOUT TIME ZONE NULL,
    response_status INTEGER NULL,
    response_digest CHAR(64) NULL,
    last_error_code VARCHAR(128) NULL,
    status SMALLINT NOT NULL DEFAULT 1,
    create_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_oidc_logout_delivery_event UNIQUE (event_id),
    CONSTRAINT ck_sand_iam_oidc_logout_delivery_state CHECK (state IN ('pending', 'sending', 'delivered', 'dead')),
    CONSTRAINT ck_sand_iam_oidc_logout_delivery_attempt CHECK (attempt_count BETWEEN 0 AND 5),
    CONSTRAINT ck_sand_iam_oidc_logout_delivery_status CHECK (status IN (1, 2)),
    CONSTRAINT fk_sand_iam_oidc_logout_delivery_app FOREIGN KEY (application_id) REFERENCES sand_iam_application (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oidc_logout_delivery_client FOREIGN KEY (oauth_client_id) REFERENCES sand_iam_oauth_client (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_oidc_logout_delivery_session FOREIGN KEY (auth_session_id) REFERENCES sand_iam_auth_session (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_oidc_logout_delivery_pending
    ON sand_iam_oidc_logout_delivery (next_attempt_time, id)
    WHERE state = 'pending' AND status = 1;

-- lifecycle source: migrations/017_cas_protocol.pgsql
BEGIN;

CREATE TABLE IF NOT EXISTS sand_iam_cas_service (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    name varchar(128) NOT NULL,
    service_url varchar(512) NOT NULL,
    released_attributes jsonb NOT NULL DEFAULT '[]'::jsonb,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_cas_service_url UNIQUE (service_url)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_cas_service_app_status
    ON sand_iam_cas_service (application_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_cas_login_request (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    cas_service_id bigint NOT NULL REFERENCES sand_iam_cas_service(id),
    request_hash char(64) NOT NULL,
    expire_time timestamp without time zone NOT NULL,
    consumed_time timestamp without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_cas_login_request_hash UNIQUE (request_hash)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_cas_login_request_expire
    ON sand_iam_cas_login_request (status, expire_time);

CREATE TABLE IF NOT EXISTS sand_iam_cas_ticket (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    cas_service_id bigint NOT NULL REFERENCES sand_iam_cas_service(id),
    identity_id bigint NOT NULL REFERENCES sand_iam_identity(id),
    ticket_hash char(64) NOT NULL,
    expire_time timestamp without time zone NOT NULL,
    consumed_time timestamp without time zone NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_cas_ticket_hash UNIQUE (ticket_hash)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_cas_ticket_expire
    ON sand_iam_cas_ticket (status, expire_time);
CREATE INDEX IF NOT EXISTS idx_sand_iam_cas_ticket_identity
    ON sand_iam_cas_ticket (application_id, identity_id, create_time DESC);

COMMIT;

-- lifecycle source: migrations/018_radius_server.pgsql
BEGIN;

CREATE TABLE IF NOT EXISTS sand_iam_radius_nas (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    name varchar(128) NOT NULL,
    source_cidr cidr NOT NULL,
    encrypted_shared_secret text NULL,
    secret_version varchar(32) NULL,
    accounting_enabled boolean NOT NULL DEFAULT false,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_radius_nas_source UNIQUE (source_cidr)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_radius_nas_app_status
    ON sand_iam_radius_nas (application_id, status);

CREATE TABLE IF NOT EXISTS sand_iam_radius_replay (
    id bigserial PRIMARY KEY,
    radius_nas_id bigint NOT NULL REFERENCES sand_iam_radius_nas(id) ON DELETE CASCADE,
    request_fingerprint char(64) NOT NULL,
    expire_time timestamp without time zone NOT NULL,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_radius_replay UNIQUE (radius_nas_id, request_fingerprint)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_radius_replay_expire
    ON sand_iam_radius_replay (expire_time);

CREATE TABLE IF NOT EXISTS sand_iam_radius_accounting_session (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    radius_nas_id bigint NOT NULL REFERENCES sand_iam_radius_nas(id),
    session_reference char(64) NOT NULL,
    user_reference char(64) NULL,
    state varchar(16) NOT NULL CHECK (state IN ('active', 'stopped')),
    start_time timestamp without time zone NOT NULL,
    last_event_time timestamp without time zone NOT NULL,
    stop_time timestamp without time zone NULL,
    session_seconds bigint NOT NULL DEFAULT 0 CHECK (session_seconds >= 0),
    input_octets bigint NOT NULL DEFAULT 0 CHECK (input_octets >= 0),
    output_octets bigint NOT NULL DEFAULT 0 CHECK (output_octets >= 0),
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_radius_accounting_active
    ON sand_iam_radius_accounting_session (radius_nas_id, session_reference)
    WHERE state = 'active';
CREATE INDEX IF NOT EXISTS idx_sand_iam_radius_accounting_app_time
    ON sand_iam_radius_accounting_session (application_id, last_event_time DESC);

CREATE TABLE IF NOT EXISTS sand_iam_radius_accounting_event (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id),
    radius_nas_id bigint NOT NULL REFERENCES sand_iam_radius_nas(id),
    accounting_session_id bigint NULL REFERENCES sand_iam_radius_accounting_session(id),
    session_reference char(64) NOT NULL,
    user_reference char(64) NULL,
    request_fingerprint char(64) NOT NULL,
    event_type varchar(16) NOT NULL CHECK (event_type IN ('start', 'interim', 'stop')),
    outcome varchar(16) NOT NULL CHECK (outcome IN ('applied', 'orphaned', 'conflict')),
    event_time timestamp without time zone NOT NULL,
    session_seconds bigint NOT NULL DEFAULT 0 CHECK (session_seconds >= 0),
    input_octets bigint NOT NULL DEFAULT 0 CHECK (input_octets >= 0),
    output_octets bigint NOT NULL DEFAULT 0 CHECK (output_octets >= 0),
    create_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_radius_accounting_event UNIQUE (radius_nas_id, request_fingerprint)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_radius_accounting_event_time
    ON sand_iam_radius_accounting_event (application_id, event_time DESC);

COMMIT;

-- lifecycle source: migrations/019_security_operations.pgsql
-- SandIAM 0.12: application IP allowlist, audit retention/archive and alerts.
-- This immutable migration is not wired into root lifecycle SQL until the
-- separately authorized PostgreSQL lifecycle acceptance.

CREATE TABLE IF NOT EXISTS sand_iam_application_network_policy (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE CASCADE,
    allow_cidrs jsonb NOT NULL DEFAULT '[]'::jsonb,
    deny_cidrs jsonb NOT NULL DEFAULT '[]'::jsonb,
    status smallint NOT NULL DEFAULT 1,
    created_by bigint NULL,
    updated_by bigint NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_application_network_policy UNIQUE (application_id),
    CONSTRAINT ck_sand_iam_application_network_policy_status CHECK (status IN (1, 2)),
    CONSTRAINT ck_sand_iam_application_network_policy_allow CHECK (jsonb_typeof(allow_cidrs) = 'array'),
    CONSTRAINT ck_sand_iam_application_network_policy_deny CHECK (jsonb_typeof(deny_cidrs) = 'array')
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_application_network_policy_status ON sand_iam_application_network_policy(status);

CREATE TABLE IF NOT EXISTS sand_iam_audit_retention_policy (
    id bigserial PRIMARY KEY,
    organization_id bigint NOT NULL REFERENCES sand_iam_organization(id) ON DELETE CASCADE,
    archive_after_days integer NOT NULL DEFAULT 90,
    retention_days integer NOT NULL DEFAULT 365,
    purge_enabled boolean NOT NULL DEFAULT false,
    alert_window_seconds integer NOT NULL DEFAULT 300,
    alert_failure_threshold integer NOT NULL DEFAULT 5,
    status smallint NOT NULL DEFAULT 1,
    created_by bigint NULL,
    updated_by bigint NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_audit_retention_policy UNIQUE (organization_id),
    CONSTRAINT ck_sand_iam_audit_retention_range CHECK (archive_after_days BETWEEN 1 AND 3650 AND retention_days BETWEEN archive_after_days AND 3650),
    CONSTRAINT ck_sand_iam_audit_alert_window CHECK (alert_window_seconds BETWEEN 60 AND 86400),
    CONSTRAINT ck_sand_iam_audit_alert_threshold CHECK (alert_failure_threshold BETWEEN 2 AND 10000),
    CONSTRAINT ck_sand_iam_audit_retention_status CHECK (status IN (1, 2))
);

CREATE TABLE IF NOT EXISTS sand_iam_audit_archive (
    id bigserial PRIMARY KEY,
    original_audit_id bigint NOT NULL,
    actor_type varchar(32) NOT NULL,
    actor_ref varchar(128) NOT NULL,
    organization_id bigint NULL,
    application_id bigint NULL,
    action varchar(96) NOT NULL,
    resource_type varchar(64) NOT NULL,
    resource_id bigint NULL,
    outcome varchar(32) NOT NULL,
    request_id varchar(96) NOT NULL,
    context jsonb NOT NULL DEFAULT '{}'::jsonb,
    original_create_time timestamp(0) without time zone NOT NULL,
    archive_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_audit_archive_original UNIQUE (original_audit_id)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_audit_archive_org_time ON sand_iam_audit_archive(organization_id, original_create_time DESC);
CREATE INDEX IF NOT EXISTS idx_sand_iam_audit_archive_request ON sand_iam_audit_archive(request_id);

CREATE TABLE IF NOT EXISTS sand_iam_security_alert (
    id bigserial PRIMARY KEY,
    organization_id bigint NOT NULL REFERENCES sand_iam_organization(id) ON DELETE CASCADE,
    application_id bigint NULL REFERENCES sand_iam_application(id) ON DELETE CASCADE,
    rule_code varchar(64) NOT NULL,
    severity varchar(16) NOT NULL,
    fingerprint char(64) NOT NULL,
    occurrence_count integer NOT NULL DEFAULT 1,
    first_seen_time timestamp(0) without time zone NOT NULL,
    last_seen_time timestamp(0) without time zone NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'open',
    resolved_by bigint NULL,
    resolved_time timestamp(0) without time zone NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_security_alert_severity CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    CONSTRAINT ck_sand_iam_security_alert_status CHECK (status IN ('open', 'acknowledged', 'resolved'))
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_security_alert_scope ON sand_iam_security_alert(organization_id, application_id, status, last_seen_time DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_security_alert_open ON sand_iam_security_alert(organization_id, fingerprint) WHERE status = 'open';

-- lifecycle source: migrations/020_initialization_package.pgsql
-- SandIAM 0.12: reviewable initialization packages and rollback records.
-- No secrets, identities or business data may be stored in these tables.

CREATE TABLE IF NOT EXISTS sand_iam_initialization_run (
    id bigserial PRIMARY KEY,
    organization_id bigint NOT NULL REFERENCES sand_iam_organization(id) ON DELETE RESTRICT,
    application_id bigint NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    package_code varchar(64) NOT NULL,
    package_hash char(64) NOT NULL,
    preview_hash char(64) NOT NULL,
    manifest jsonb NOT NULL,
    changes jsonb NOT NULL,
    state varchar(16) NOT NULL DEFAULT 'applied',
    applied_by bigint NOT NULL,
    applied_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rollback_by bigint NULL,
    rollback_time timestamp(0) without time zone NULL,
    request_id varchar(96) NOT NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_initialization_run_state CHECK (state IN ('applied', 'rolled_back'))
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_initialization_run_scope ON sand_iam_initialization_run(organization_id, application_id, applied_time DESC);
CREATE INDEX IF NOT EXISTS idx_sand_iam_initialization_run_package ON sand_iam_initialization_run(package_code, package_hash);

CREATE TABLE IF NOT EXISTS sand_iam_initialization_binding (
    id bigserial PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE CASCADE,
    package_code varchar(64) NOT NULL,
    object_type varchar(32) NOT NULL,
    object_key varchar(128) NOT NULL,
    table_name varchar(64) NOT NULL,
    resource_id bigint NOT NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_initialization_binding UNIQUE (application_id, package_code, object_type, object_key),
    CONSTRAINT ck_sand_iam_initialization_binding_type CHECK (object_type IN ('application', 'role', 'user_type', 'resource', 'identity_provider', 'policy', 'application_business_action')),
    CONSTRAINT ck_sand_iam_initialization_binding_table CHECK (table_name IN ('sand_iam_application', 'sand_iam_role', 'sand_iam_user_type', 'sand_iam_resource', 'sand_iam_identity_provider', 'sand_iam_policy', 'sand_iam_application_business_action'))
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_initialization_binding_resource ON sand_iam_initialization_binding(table_name, resource_id);

-- lifecycle source: migrations/021_admin_permission_catalog.pgsql
-- SandIAM terminal administration permission catalog.
-- Permission nodes stay hidden; operators see task paths instead of a flat
-- list of machine actions. Chinese names describe the actual operation.
BEGIN;

WITH permission_group(resource_code, resource_name, parent_code, base_sort, actions) AS (
    VALUES
        ('admin_application_grant', '应用管理委派', 'SandIAMConnection', 2100, ARRAY['index','read','save','update','disable']::text[]),
        ('application_experience', '登录与用户体验', 'SandIAMConnection', 2080, ARRAY['index','read','save','update','disable']::text[]),
        ('message_provider', '消息服务商', 'SandIAMConnection', 2060, ARRAY['index','read','save','update','configure','test','disable']::text[]),
        ('message_provider_mount', '应用消息服务', 'SandIAMConnection', 2040, ARRAY['index','save','disable']::text[]),
        ('initialization', '应用初始化方案', 'SandIAMConnection', 2020, ARRAY['index','read','preview','apply','rollback','export']::text[]),
        -- Explicit assignment only: onboarding can create or change several
        -- application-scoped authorization records in one operation.
        ('onboarding', '开发者接入', 'SandIAMConnection', 2010, ARRAY['preview','apply']::text[]),

        ('api_resource', '接口资源', 'SandIAMPeopleAccess', 2000, ARRAY['index','read','save','update','disable']::text[]),
        ('api_route_binding', '接口路由绑定', 'SandIAMPeopleAccess', 1980, ARRAY['index','read','save','update','disable']::text[]),
        ('cas_service', 'CAS 接入服务', 'SandIAMPeopleAccess', 1960, ARRAY['index','read','save','update','disable']::text[]),
        ('identity', '应用用户', 'SandIAMPeopleAccess', 1940, ARRAY['enable','delete','restore']::text[]),
        ('identity_export', '应用用户导出', 'SandIAMPeopleAccess', 1920, ARRAY['masked','sensitive']::text[]),
        ('identity_group', '用户组', 'SandIAMPeopleAccess', 1900, ARRAY['index','read','save','update','disable']::text[]),
        ('identity_group_member', '用户组成员', 'SandIAMPeopleAccess', 1880, ARRAY['index','add','remove']::text[]),
        ('identity_import', '应用用户导入', 'SandIAMPeopleAccess', 1860, ARRAY['index','read','preview','confirm']::text[]),
        ('identity_invitation', '用户邀请', 'SandIAMPeopleAccess', 1840, ARRAY['index','read','send','resend','revoke']::text[]),
        ('oauth_registration_token', 'OAuth 动态注册令牌', 'SandIAMPeopleAccess', 1820, ARRAY['index','issue','revoke']::text[]),
        ('radius_nas', 'RADIUS 接入设备', 'SandIAMPeopleAccess', 1800, ARRAY['index','read','save','update','configure','disable']::text[]),
        ('sync_connector', '身份同步连接器', 'SandIAMPeopleAccess', 1780, ARRAY['index','read','save','update','configure','test','disable']::text[]),
        ('sync_run', '身份同步任务', 'SandIAMPeopleAccess', 1760, ARRAY['index','run']::text[]),

        ('audit', '访问审计', 'SandIAMAuditTroubleshooting', 1740, ARRAY['export']::text[]),
        ('application_network_policy', '应用访问网络规则', 'SandIAMAuditTroubleshooting', 1720, ARRAY['index','read','save','update','disable']::text[]),
        ('audit_retention_policy', '审计保留规则', 'SandIAMAuditTroubleshooting', 1700, ARRAY['index','read','save','update','disable']::text[]),
        ('developer', '开发者资料', 'SandIAMAuditTroubleshooting', 1680, ARRAY['openapi','events']::text[]),
        ('security_alert', '安全告警', 'SandIAMAuditTroubleshooting', 1660, ARRAY['index','read','resolve']::text[]),
        ('webhook', '事件通知地址', 'SandIAMAuditTroubleshooting', 1640, ARRAY['index','read','save','update','disable']::text[]),
        ('webhook_delivery', '事件通知记录', 'SandIAMAuditTroubleshooting', 1620, ARRAY['index','read','retry']::text[])
), permission_def AS (
    SELECT
        permission_group.resource_code,
        permission_group.resource_name,
        permission_group.parent_code,
        permission_group.base_sort + action.position::integer AS sort,
        action.code AS action_code,
        'sand_iam:' || permission_group.resource_code || ':' || action.code AS permission_code,
        CASE
            WHEN permission_group.resource_code = 'onboarding' AND action.code = 'preview' THEN '开发者接入预检'
            WHEN permission_group.resource_code = 'onboarding' AND action.code = 'apply' THEN '确认应用开发者接入清单'
            ELSE permission_group.resource_name || CASE action.code
            WHEN 'index' THEN '查看'
            WHEN 'read' THEN '查看详情'
            WHEN 'save' THEN '新建'
            WHEN 'update' THEN '编辑'
            WHEN 'disable' THEN '停用'
            WHEN 'enable' THEN '启用'
            WHEN 'delete' THEN '删除'
            WHEN 'restore' THEN '恢复'
            WHEN 'export' THEN '导出'
            WHEN 'masked' THEN '脱敏导出'
            WHEN 'sensitive' THEN '敏感导出'
            WHEN 'add' THEN '添加'
            WHEN 'remove' THEN '移除'
            WHEN 'preview' THEN '预检'
            WHEN 'confirm' THEN '确认导入'
            WHEN 'send' THEN '发出邀请'
            WHEN 'resend' THEN '重新发送'
            WHEN 'revoke' THEN '撤销'
            WHEN 'configure' THEN '配置'
            WHEN 'test' THEN '测试连接'
            WHEN 'openapi' THEN '查看接口文档'
            WHEN 'events' THEN '查看事件目录'
            WHEN 'apply' THEN '应用方案'
            WHEN 'rollback' THEN '回滚'
            WHEN 'issue' THEN '签发'
            WHEN 'resolve' THEN '处理'
            WHEN 'run' THEN '执行'
            WHEN 'retry' THEN '重试'
            ELSE action.code
            END
        END AS permission_name
    FROM permission_group
    CROSS JOIN LATERAL unnest(permission_group.actions) WITH ORDINALITY AS action(code, position)
), permission_menu AS (
    SELECT parent.id AS parent_id,
           permission_def.resource_code,
           permission_def.resource_name,
           permission_def.parent_code,
           permission_def.sort,
           permission_def.action_code,
           permission_def.permission_code,
           permission_def.permission_code AS slug,
           permission_def.permission_name
    FROM permission_def
    JOIN LATERAL (
        SELECT id FROM sand_system_menu WHERE code = permission_def.parent_code ORDER BY id LIMIT 1
    ) parent ON TRUE
), refresh_existing AS (
    -- Earlier 021 revisions used a short dashed slug. SandAdmin's non-super
    -- administrator permission middleware compares the type=3 slug with the
    -- controller Permission code, so correct existing rows before inserting.
    UPDATE sand_system_menu existing
    SET parent_id = desired.parent_id,
        name = desired.permission_name,
        slug = desired.permission_code,
        is_hidden = 1,
        status = 1,
        update_time = CURRENT_TIMESTAMP
    FROM permission_menu desired
    WHERE existing.type = 3
      AND existing.code = desired.permission_code
      AND (
          existing.parent_id IS DISTINCT FROM desired.parent_id
          OR existing.name IS DISTINCT FROM desired.permission_name
          OR existing.slug IS DISTINCT FROM desired.permission_code
          OR existing.is_hidden IS DISTINCT FROM 1
          OR existing.status IS DISTINCT FROM 1
      )
    RETURNING existing.id
)
INSERT INTO sand_system_menu (parent_id, name, code, slug, type, path, component, icon, sort, is_hidden, status, create_time, update_time)
SELECT permission_menu.parent_id, permission_menu.permission_name, permission_menu.permission_code, permission_menu.slug,
       3, '', '', '', permission_menu.sort, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM permission_menu
WHERE NOT EXISTS (
    SELECT 1 FROM sand_system_menu known WHERE known.code = permission_menu.permission_code
);

INSERT INTO sand_system_role_menu (role_id, menu_id)
SELECT DISTINCT inherited.role_id, permission.id
FROM sand_system_role_menu inherited
JOIN sand_system_menu parent
  ON parent.id = inherited.menu_id
 AND parent.code IN ('SandIAMConnection', 'SandIAMPeopleAccess', 'SandIAMAuditTroubleshooting')
JOIN sand_system_menu permission
  ON permission.parent_id = parent.id
 AND permission.code LIKE 'sand\_iam:%' ESCAPE '\'
 AND permission.code NOT IN (
     'sand_iam:onboarding:preview',
     'sand_iam:onboarding:apply',
     'sand_iam:api_resource:index',
     'sand_iam:api_route_binding:index'
 )
WHERE NOT EXISTS (
    SELECT 1
    FROM sand_system_role_menu existing
    WHERE existing.role_id = inherited.role_id
      AND existing.menu_id = permission.id
);

COMMIT;

