-- lifecycle source: migrations/023_federation_protocol_constraint_alignment.pgsql
-- Align database protocol constraints with the supported federation services.
BEGIN;

ALTER TABLE sand_iam_identity_provider
    DROP CONSTRAINT IF EXISTS ck_sand_iam_identity_provider_type;
ALTER TABLE sand_iam_identity_provider
    ADD CONSTRAINT ck_sand_iam_identity_provider_type
    CHECK (provider_type IN ('local', 'oidc', 'oauth2', 'saml', 'ldap', 'scim', 'kerberos'));

ALTER TABLE sand_iam_federation_transaction
    DROP CONSTRAINT IF EXISTS sand_iam_federation_transaction_protocol_check;
ALTER TABLE sand_iam_federation_transaction
    DROP CONSTRAINT IF EXISTS ck_sand_iam_federation_transaction_protocol;
ALTER TABLE sand_iam_federation_transaction
    ADD CONSTRAINT ck_sand_iam_federation_transaction_protocol
    CHECK (protocol IN ('oidc', 'oauth2', 'saml'));

COMMIT;

-- lifecycle source: migrations/024_scim_group_member_lifecycle.pgsql
-- SandIAM SCIM group member lifecycle contract.
-- Membership removal is reversible: status records the business state while
-- delete_time is managed by the model's soft-delete concern.

ALTER TABLE sand_iam_scim_group_member
    ADD COLUMN IF NOT EXISTS status smallint NOT NULL DEFAULT 1,
    ADD COLUMN IF NOT EXISTS update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;

DO $$ BEGIN ALTER TABLE sand_iam_scim_group_member ADD CONSTRAINT ck_sand_iam_scim_group_member_status CHECK (status IN (1, 2)); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE INDEX IF NOT EXISTS idx_sand_iam_scim_group_member_group_status
    ON sand_iam_scim_group_member (group_id, status);

-- lifecycle source: migrations/025_message_provider_mount_scope_integrity.pgsql
-- SandIAM message provider mount scope integrity.
-- A mount may only connect an application and provider owned by the same
-- organization. Controller validation is not a substitute for database
-- isolation because imports and future workers can also write this table.

DO $$ BEGIN ALTER TABLE sand_iam_message_provider ADD CONSTRAINT uk_sand_iam_message_provider_id_organization UNIQUE (id, organization_id); EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;

DO $$ BEGIN ALTER TABLE sand_iam_message_provider_application ADD CONSTRAINT fk_sand_iam_message_mount_provider_organization FOREIGN KEY (message_provider_id, organization_id) REFERENCES sand_iam_message_provider(id, organization_id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;

DO $$ BEGIN ALTER TABLE sand_iam_message_provider_application ADD CONSTRAINT fk_sand_iam_message_mount_application_organization FOREIGN KEY (application_id, organization_id) REFERENCES sand_iam_application(id, organization_id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;

-- lifecycle source: migrations/026_sync_connector_scope_integrity.pgsql
-- SandIAM sync connector scope integrity.
-- The connector's organization is denormalized for administration and audit,
-- but it must always match the owning application's organization.

DO $$ BEGIN ALTER TABLE sand_iam_sync_connector ADD CONSTRAINT fk_sand_iam_sync_connector_application_organization FOREIGN KEY (application_id, organization_id) REFERENCES sand_iam_application(id, organization_id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object OR duplicate_table THEN NULL; END $$;

-- lifecycle source: migrations/027_security_operation_idempotency.pgsql
CREATE TABLE IF NOT EXISTS sand_iam_security_operation (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_type varchar(32) NOT NULL,
    actor_ref varchar(128) NOT NULL,
    operation varchar(96) NOT NULL,
    request_id varchar(96) NOT NULL,
    request_fingerprint char(64) NOT NULL,
    resource_type varchar(64) NOT NULL,
