ALTER TABLE sand_iam_security_operation ADD COLUMN IF NOT EXISTS state varchar(16);
ALTER TABLE sand_iam_security_operation ADD COLUMN IF NOT EXISTS result jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE sand_iam_security_operation ADD COLUMN IF NOT EXISTS create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE sand_iam_security_operation ADD COLUMN IF NOT EXISTS update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_sand_iam_security_operation_actor_request' AND conrelid = 'sand_iam_security_operation'::regclass) THEN ALTER TABLE sand_iam_security_operation ADD CONSTRAINT uk_sand_iam_security_operation_actor_request UNIQUE (actor_type, actor_ref, operation, request_id); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_security_operation_state' AND conrelid = 'sand_iam_security_operation'::regclass) THEN ALTER TABLE sand_iam_security_operation ADD CONSTRAINT ck_sand_iam_security_operation_state CHECK (state IN ('pending', 'succeeded')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_security_operation_fingerprint' AND conrelid = 'sand_iam_security_operation'::regclass) THEN ALTER TABLE sand_iam_security_operation ADD CONSTRAINT ck_sand_iam_security_operation_fingerprint CHECK (request_fingerprint ~ '^[0-9a-f]{64}$'); END IF; END $$;

