-- lifecycle source: migrations/028_application_business_action.pgsql
-- Application-owned business-action vocabulary.
--
-- Compatibility policy: deliberately do not backfill sand_iam_api_resource.action
-- or sand_iam_policy.action. Existing free strings are not evidence of a valid
-- declaration; the management API exposes them as pending_claim records for a
-- human operator to review and claim explicitly.
-- This table is intentionally unrelated to sand_iam_service_action.

CREATE TABLE IF NOT EXISTS sand_iam_application_business_action (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    code varchar(96) NOT NULL,
    name varchar(128) NOT NULL,
    description varchar(500) NOT NULL DEFAULT '',
    state varchar(16) NOT NULL DEFAULT 'draft',
    status smallint NOT NULL DEFAULT 1,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL
);

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'sand_iam_application_business_action'::regclass AND conname = 'sand_iam_application_business_action_code_check') THEN ALTER TABLE sand_iam_application_business_action ADD CONSTRAINT sand_iam_application_business_action_code_check CHECK (code ~ '^[a-z][a-z0-9_.:-]{1,95}$'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'sand_iam_application_business_action'::regclass AND conname = 'sand_iam_application_business_action_state_check') THEN ALTER TABLE sand_iam_application_business_action ADD CONSTRAINT sand_iam_application_business_action_state_check CHECK (state IN ('draft', 'published')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'sand_iam_application_business_action'::regclass AND conname = 'sand_iam_application_business_action_status_check') THEN ALTER TABLE sand_iam_application_business_action ADD CONSTRAINT sand_iam_application_business_action_status_check CHECK (status IN (1, 2)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'sand_iam_application_business_action'::regclass AND conname = 'sand_iam_application_business_action_application_code_unique') THEN ALTER TABLE sand_iam_application_business_action ADD CONSTRAINT sand_iam_application_business_action_application_code_unique UNIQUE (application_id, code); END IF; END $$;

CREATE INDEX IF NOT EXISTS sand_iam_application_business_action_application_status_idx
    ON sand_iam_application_business_action (application_id, status);

COMMENT ON TABLE sand_iam_application_business_action IS 'Application-owned declared business actions; never service integration actions.';
COMMENT ON COLUMN sand_iam_application_business_action.code IS 'Stable action code. Management API never updates code after creation; published declarations are immutable by contract.';

-- lifecycle source: migrations/029_policy_versioning.pgsql
-- Immutable published policy snapshots. Runtime uses published_version_id only.
CREATE TABLE IF NOT EXISTS sand_iam_policy_version (
    id bigserial PRIMARY KEY,
    policy_id bigint NOT NULL REFERENCES sand_iam_policy(id) ON DELETE CASCADE,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE CASCADE,
    version_no integer NOT NULL,
    snapshot jsonb NOT NULL,
    snapshot_hash varchar(64) NOT NULL,
    rollback_of_version_id bigint NULL REFERENCES sand_iam_policy_version(id) ON DELETE RESTRICT,
    operation varchar(16) NOT NULL DEFAULT 'publish',
    request_id varchar(96) NOT NULL,
    request_fingerprint varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_policy_version_no UNIQUE (policy_id, version_no),
    CONSTRAINT uk_sand_iam_policy_version_request UNIQUE (policy_id, request_id)
);
ALTER TABLE sand_iam_policy ADD COLUMN IF NOT EXISTS published_version_id bigint NULL;
ALTER TABLE sand_iam_policy_version ADD COLUMN IF NOT EXISTS operation varchar(16) NOT NULL DEFAULT 'publish';
ALTER TABLE sand_iam_policy_version ADD COLUMN IF NOT EXISTS request_fingerprint varchar(64) NOT NULL DEFAULT '';
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_sand_iam_policy_published_version') THEN ALTER TABLE sand_iam_policy ADD CONSTRAINT fk_sand_iam_policy_published_version FOREIGN KEY (published_version_id) REFERENCES sand_iam_policy_version(id) ON DELETE RESTRICT; END IF; END $$;
CREATE INDEX IF NOT EXISTS idx_sand_iam_policy_version_application ON sand_iam_policy_version(application_id, policy_id, version_no DESC);
CREATE INDEX IF NOT EXISTS idx_sand_iam_policy_published_version ON sand_iam_policy(published_version_id);

-- lifecycle source: migrations/030_service_grant_invocation_control.pgsql
BEGIN;

DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_service_grant_data_class' AND conrelid = 'sand_iam_service_grant'::regclass ) THEN ALTER TABLE sand_iam_service_grant ADD CONSTRAINT ck_sand_iam_service_grant_data_class CHECK (data_class IS NULL OR data_class ~ '^[a-z0-9][a-z0-9._-]{1,31}$') NOT VALID; END IF; IF NOT EXISTS ( SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_service_grant_quota_object' AND conrelid = 'sand_iam_service_grant'::regclass ) THEN ALTER TABLE sand_iam_service_grant ADD CONSTRAINT ck_sand_iam_service_grant_quota_object CHECK (quota_policy IS NULL OR jsonb_typeof(quota_policy) = 'object') NOT VALID; END IF; END $$;

CREATE TABLE IF NOT EXISTS sand_iam_service_invocation_operation (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workload_client_id bigint NOT NULL REFERENCES sand_iam_workload_client(id) ON DELETE RESTRICT,
    credential_id bigint NOT NULL REFERENCES sand_iam_credential(id) ON DELETE RESTRICT,
    organization_id bigint NOT NULL REFERENCES sand_iam_organization(id) ON DELETE RESTRICT,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    environment_id bigint NOT NULL REFERENCES sand_iam_environment(id) ON DELETE RESTRICT,
    grant_id bigint NOT NULL REFERENCES sand_iam_service_grant(id) ON DELETE RESTRICT,
    operation_id varchar(96) NOT NULL,
    request_fingerprint varchar(64) NOT NULL,
    context_id varchar(64) NOT NULL,
    service_code varchar(64) NOT NULL,
    action_code varchar(96) NOT NULL,
    audience varchar(128) NOT NULL,
    data_class varchar(32) NULL,
    resource_type varchar(64) NOT NULL,
    resource_ref varchar(128) NOT NULL,
    outcome varchar(16) NOT NULL DEFAULT 'pending',
    error_code varchar(96) NULL,
    request_id varchar(96) NOT NULL,
    quota_window_start timestamp(0) without time zone NULL,
    quota_used bigint NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_invocation_operation_client_operation UNIQUE (workload_client_id, operation_id),
    CONSTRAINT ck_sand_iam_invocation_operation_outcome CHECK (outcome IN ('pending', 'allowed', 'denied')),
    CONSTRAINT ck_sand_iam_invocation_operation_quota_used CHECK (quota_used IS NULL OR quota_used > 0)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_invocation_operation_grant_time
    ON sand_iam_service_invocation_operation (grant_id, create_time DESC);
CREATE INDEX IF NOT EXISTS idx_sand_iam_invocation_operation_context
    ON sand_iam_service_invocation_operation (context_id);

CREATE TABLE IF NOT EXISTS sand_iam_service_quota_bucket (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grant_id bigint NOT NULL REFERENCES sand_iam_service_grant(id) ON DELETE RESTRICT,
    window_seconds integer NOT NULL,
    window_start timestamp(0) without time zone NOT NULL,
    used bigint NOT NULL DEFAULT 0,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_sand_iam_service_quota_bucket UNIQUE (grant_id, window_seconds, window_start),
    CONSTRAINT ck_sand_iam_service_quota_bucket_window CHECK (window_seconds > 0 AND window_seconds <= 31536000),
    CONSTRAINT ck_sand_iam_service_quota_bucket_used CHECK (used >= 0)
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_service_quota_bucket_window
    ON sand_iam_service_quota_bucket (window_start DESC);

COMMIT;

-- lifecycle source: migrations/031_oidc_signing_key_rotation.pgsql
-- IAM-T12-031 BEGIN
-- OIDC has one public issuer and therefore one signing owner. OAuth clients
-- are application scoped but do not carry an environment selector; per-app or
-- per-environment signing keys would be unverifiable at this issuer-wide JWKS.
BEGIN;

ALTER TABLE sand_iam_oidc_signing_key
    ADD COLUMN IF NOT EXISTS encrypted_private_key text NULL,
    ADD COLUMN IF NOT EXISTS encryption_version varchar(32) NULL,
    ADD COLUMN IF NOT EXISTS algorithm varchar(16) NOT NULL DEFAULT 'RS256';

COMMENT ON COLUMN sand_iam_oidc_signing_key.encrypted_private_key IS 'Write-only versioned private-key envelope; NULL only when no private signing material is stored.';
COMMENT ON COLUMN sand_iam_oidc_signing_key.encryption_version IS 'Key-encryption version for encrypted_private_key; NULL when no private signing material is stored.';

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_oidc_signing_key_algorithm') THEN ALTER TABLE sand_iam_oidc_signing_key ADD CONSTRAINT ck_sand_iam_oidc_signing_key_algorithm CHECK (algorithm = 'RS256') NOT VALID; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_sand_iam_oidc_signing_key_algorithm' AND NOT convalidated) THEN ALTER TABLE sand_iam_oidc_signing_key VALIDATE CONSTRAINT ck_sand_iam_oidc_signing_key_algorithm; END IF; END $$;

-- One active database signer prevents concurrent rotations from producing two
-- valid signing authorities. Existing verify_only rows remain verification
-- history and are intentionally not affected by this invariant.
CREATE UNIQUE INDEX IF NOT EXISTS uk_sand_iam_oidc_signing_key_one_active
    ON sand_iam_oidc_signing_key ((1))
    WHERE state = 'active';

COMMIT;
-- IAM-T12-031 END

-- lifecycle source: migrations/032_initialization_binding_application_business_action.pgsql
-- Existing installations already have 020's original checks. Replacing those
-- checks here keeps upgrades compatible with application-owned action bindings.
BEGIN;

ALTER TABLE sand_iam_initialization_binding
    DROP CONSTRAINT IF EXISTS ck_sand_iam_initialization_binding_type;
ALTER TABLE sand_iam_initialization_binding
    DROP CONSTRAINT IF EXISTS ck_sand_iam_initialization_binding_table;

ALTER TABLE sand_iam_initialization_binding
    ADD CONSTRAINT ck_sand_iam_initialization_binding_type
    CHECK (object_type IN ('application', 'role', 'user_type', 'resource', 'identity_provider', 'policy', 'application_business_action'));
ALTER TABLE sand_iam_initialization_binding
    ADD CONSTRAINT ck_sand_iam_initialization_binding_table
    CHECK (table_name IN ('sand_iam_application', 'sand_iam_role', 'sand_iam_user_type', 'sand_iam_resource', 'sand_iam_identity_provider', 'sand_iam_policy', 'sand_iam_application_business_action'));

COMMIT;

-- lifecycle source: migrations/033_identity_group_role.pgsql
-- IAM-T11: role grants inherited through active user-group membership.
-- The application is the authoritative organization boundary: both referenced
-- records must carry the same application_id, which belongs to exactly one
-- SandIAM organization.

CREATE UNIQUE INDEX IF NOT EXISTS ux_sand_iam_role_id_application
    ON sand_iam_role (id, application_id);

CREATE TABLE IF NOT EXISTS sand_iam_identity_group_role (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identity_group_id bigint NOT NULL,
    role_id bigint NOT NULL,
    application_id bigint NOT NULL REFERENCES sand_iam_application(id) ON DELETE RESTRICT,
    status smallint NOT NULL DEFAULT 1 CHECK (status IN (1, 2)),
    created_by bigint NULL,
    updated_by bigint NULL,
    create_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delete_time timestamp(0) without time zone NULL,
    CONSTRAINT uk_sand_iam_identity_group_role UNIQUE (identity_group_id, role_id),
    CONSTRAINT fk_sand_iam_group_role_group_app FOREIGN KEY (identity_group_id, application_id)
        REFERENCES sand_iam_identity_group(id, application_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sand_iam_group_role_role_app FOREIGN KEY (role_id, application_id)
        REFERENCES sand_iam_role(id, application_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_sand_iam_identity_group_role_role
    ON sand_iam_identity_group_role (application_id, role_id, status);

-- lifecycle source: migrations/034_identity_group_role_permission_catalog.pgsql
-- SandIAM 0.7.0: catalog only the user-group role administration permissions.
-- The published 0.6.0 migration 021 is immutable. These permissions are not
-- inherited by existing roles because granting or revoking group roles changes
-- effective authorization and requires an explicit administrator decision.
BEGIN;

DO $$ DECLARE parent_menu_id bigint; BEGIN SELECT id INTO parent_menu_id FROM sand_system_menu WHERE code = 'SandIAMPeopleAccess' ORDER BY id LIMIT 1; IF parent_menu_id IS NULL THEN RAISE EXCEPTION 'SandIAM 0.7.0 cannot add identity-group-role permissions: parent menu SandIAMPeopleAccess is missing'; END IF; END $$;

WITH desired(code, name, sort) AS (
    VALUES
        ('sand_iam:identity_group_role:index', '查看用户组角色', 1871),
        ('sand_iam:identity_group_role:grant', '授予用户组角色', 1872),
        ('sand_iam:identity_group_role:revoke', '撤销用户组角色', 1873)
), parent AS (
    SELECT id
    FROM sand_system_menu
    WHERE code = 'SandIAMPeopleAccess'
    ORDER BY id
    LIMIT 1
), refresh_existing AS (
    UPDATE sand_system_menu existing
    SET parent_id = parent.id,
        name = desired.name,
        slug = desired.code,
        type = 3,
        path = '',
        component = '',
        icon = '',
        sort = desired.sort,
        is_hidden = 1,
        status = 1,
        update_time = CURRENT_TIMESTAMP
    FROM desired
    CROSS JOIN parent
    WHERE existing.code = desired.code
      AND (
          existing.parent_id IS DISTINCT FROM parent.id
          OR existing.name IS DISTINCT FROM desired.name
          OR existing.slug IS DISTINCT FROM desired.code
          OR existing.type IS DISTINCT FROM 3
          OR existing.path IS DISTINCT FROM ''
          OR existing.component IS DISTINCT FROM ''
          OR existing.icon IS DISTINCT FROM ''
          OR existing.sort IS DISTINCT FROM desired.sort
          OR existing.is_hidden IS DISTINCT FROM 1
          OR existing.status IS DISTINCT FROM 1
      )
    RETURNING existing.id
)
INSERT INTO sand_system_menu (parent_id, name, code, slug, type, path, component, icon, sort, is_hidden, status, create_time, update_time)
SELECT parent.id, desired.name, desired.code, desired.code,
       3, '', '', '', desired.sort, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM desired
CROSS JOIN parent
WHERE NOT EXISTS (
    SELECT 1
    FROM sand_system_menu existing
    WHERE existing.code = desired.code
);

COMMIT;

-- lifecycle source: migrations/035_schema_migration_ledger.pgsql
-- SandIAM 0.7.0 migration ledger.
-- There was no database migration ledger in the published 0.6.0 package. The
-- first run therefore adopts its known baseline only after checking the
-- structural version sentinels below; it never treats an empty ledger alone as
-- evidence that a database is compatible.
BEGIN;

CREATE TABLE IF NOT EXISTS sand_iam_schema_migration (
    migration_file varchar(160) PRIMARY KEY,
    revision smallint NOT NULL,
    checksum char(64) NOT NULL,
    package_version varchar(32) NOT NULL,
    executed_time timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sand_iam_schema_migration_revision CHECK (revision BETWEEN 1 AND 999),
    CONSTRAINT ck_sand_iam_schema_migration_checksum CHECK (checksum ~ '^[0-9a-f]{64}$')
);

DO $$ DECLARE required_columns integer; matched_columns integer; base_tables text[] := ARRAY['sand_iam_admin_application_grant','sand_iam_admin_organization_grant','sand_iam_api_resource','sand_iam_api_route_binding','sand_iam_application','sand_iam_application_business_action','sand_iam_application_experience','sand_iam_application_network_policy','sand_iam_audit_archive','sand_iam_audit_log','sand_iam_audit_retention_policy','sand_iam_auth_challenge','sand_iam_auth_policy','sand_iam_auth_rate_limit','sand_iam_auth_refresh_token','sand_iam_auth_session','sand_iam_auth_verification','sand_iam_authorization_code','sand_iam_cas_login_request','sand_iam_cas_service','sand_iam_cas_ticket','sand_iam_credential','sand_iam_directory_sync_run','sand_iam_environment','sand_iam_federation_handoff','sand_iam_federation_transaction','sand_iam_identity','sand_iam_identity_auth','sand_iam_identity_binding','sand_iam_identity_group','sand_iam_identity_group_member','sand_iam_identity_import_job','sand_iam_identity_import_row','sand_iam_identity_invitation','sand_iam_identity_provider','sand_iam_identity_provider_application','sand_iam_identity_role','sand_iam_identity_user_type','sand_iam_initialization_binding','sand_iam_initialization_run','sand_iam_message_provider','sand_iam_message_provider_application','sand_iam_mfa_factor','sand_iam_mfa_recovery_code','sand_iam_oauth_authorization_request','sand_iam_oauth_client','sand_iam_oauth_consent','sand_iam_oauth_grant','sand_iam_oauth_registration_token','sand_iam_oauth_token','sand_iam_oidc_logout_delivery','sand_iam_oidc_signing_key','sand_iam_organization','sand_iam_policy','sand_iam_policy_version','sand_iam_provisioning_event','sand_iam_radius_accounting_event','sand_iam_radius_accounting_session','sand_iam_radius_nas','sand_iam_radius_replay','sand_iam_resource','sand_iam_role','sand_iam_scim_group','sand_iam_scim_group_member','sand_iam_scim_resource','sand_iam_scim_token','sand_iam_security_alert','sand_iam_security_operatio