_iam_application(id, organization_id) ON DELETE RESTRICT', NULL), ('sand_iam_initialization_draft', 'uk_sand_iam_initialization_draft_organization_package', 'u', 'UNIQUE (organization_id, package_code)', NULL), ('sand_iam_initialization_draft', 'ck_sand_iam_initialization_draft_code', 'c', NULL, 'checkpackage_code~''^[a-z0-9][a-z0-9_-]{1,63}$'''), ('sand_iam_initialization_draft', 'ck_sand_iam_initialization_draft_hash', 'c', NULL, 'checkmanifest_hash~''^[a-f0-9]{64}$'''), ('sand_iam_initialization_draft', 'ck_sand_iam_initialization_draft_revision', 'c', NULL, 'checkrevision>=1'), ('sand_iam_initialization_draft', 'ck_sand_iam_initialization_draft_status', 'c', NULL, 'checkstatus=anyarray[1,2]'), ('sand_iam_initialization_draft_revision', 'sand_iam_initialization_draft_revision_pkey', 'p', 'PRIMARY KEY (id)', NULL), ('sand_iam_initialization_draft_revision', 'sand_iam_initialization_draft_revision_draft_id_fkey', 'f', 'FOREIGN KEY (draft_id) REFERENCES sand_iam_initialization_draft(id) ON DELETE RESTRICT', NULL), ('sand_iam_initialization_draft_revision', 'uk_sand_iam_initialization_draft_revision', 'u', 'UNIQUE (draft_id, revision)', NULL), ('sand_iam_initialization_draft_revision', 'ck_sand_iam_initialization_draft_revision_number', 'c', NULL, 'checkrevision>=1'), ('sand_iam_initialization_draft_revision', 'ck_sand_iam_initialization_draft_revision_hash', 'c', NULL, 'checkmanifest_hash~''^[a-f0-9]{64}$'''), ('sand_iam_initialization_draft_revision', 'ck_sand_iam_initialization_draft_revision_status', 'c', NULL, 'checkstatus=anyarray[1,2]'), ('sand_iam_initialization_draft_revision', 'ck_sand_iam_initialization_draft_revision_action', 'c', NULL, 'checkaction=anyarray[''created'',''updated'',''disabled'',''restored'']'), ('sand_iam_initialization_draft_revision', 'ck_sand_iam_initialization_draft_revision_request', 'c', NULL, 'checkrequest_id~''^[a-za-z0-9][a-za-z0-9_.:-]{7,95}$''') ) SELECT count(*) INTO matched_constraints FROM required_constraint expected JOIN pg_constraint actual_constraint ON actual_constraint.conname = expected.constraint_name AND actual_constraint.contype = expected.constraint_type JOIN pg_class actual_table ON actual_table.oid = actual_constraint.conrelid JOIN pg_namespace actual_schema ON actual_schema.oid = actual_table.relnamespace WHERE actual_schema.nspname = current_schema() AND actual_table.relname = expected.table_name AND actual_constraint.convalidated AND ( (expected.constraint_type <> 'c' AND pg_get_constraintdef(actual_constraint.oid, true) = expected.definition_token) OR (expected.constraint_type = 'c' AND regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(actual_constraint.oid, true)), E'::[a-z_][a-z0-9_]*(\\s+varying)?(\\[\\])?', '', 'g'), E'\\s+', '', 'g'), '[()]', '', 'g') = expected.normalized_check_definition) ); IF matched_constraints <> 16 OR (SELECT count(*) FROM pg_constraint actual_constraint JOIN pg_class actual_table ON actual_table.oid = actual_constraint.conrelid JOIN pg_namespace actual_schema ON actual_schema.oid = actual_table.relnamespace WHERE actual_schema.nspname = current_schema() AND actual_table.relname IN ('sand_iam_initialization_draft', 'sand_iam_initialization_draft_revision') AND actual_constraint.contype IN ('p', 'f', 'u', 'c')) <> 16 THEN RAISE EXCEPTION 'SandIAM initialization-draft constraint fingerprint is incompatible (matched %/16)', matched_constraints; END IF; WITH required_index(table_name, index_name, first_key, second_key, third_key, fourth_key, index_options) AS ( VALUES ('sand_iam_initialization_draft', 'idx_sand_iam_initialization_draft_application', 'organization_id', 'application_id', 'status', 'update_time', '0 0 0 3'), ('sand_iam_initialization_draft', 'idx_sand_iam_initialization_draft_organization', 'organization_id', 'status', 'update_time', '', '0 0 3'), ('sand_iam_initialization_draft_revision', 'idx_sand_iam_initialization_draft_revision_history', 'draft_id', 'create_time', '', '', '0 3') ) SELECT count(*) INTO matched_indexes FROM required_index expected JOIN pg_class actual_table ON actual_table.relname = expected.table_name JOIN pg_namespace actual_schema ON actual_schema.oid = actual_table.relnamespace AND actual_schema.nspname = current_schema() JOIN pg_index actual_index ON actual_index.indrelid = actual_table.oid JOIN pg_class index_relation ON index_relation.oid = actual_index.indexrelid AND index_relation.relname = expected.index_name WHERE NOT actual_index.indisunique AND actual_index.indisvalid AND actual_index.indisready AND pg_get_indexdef(actual_index.indexrelid, 1, true) = expected.first_key AND pg_get_indexdef(actual_index.indexrelid, 2, true) = expected.second_key AND pg_get_indexdef(actual_index.indexrelid, 3, true) IS NOT DISTINCT FROM expected.third_key AND pg_get_indexdef(actual_index.indexrelid, 4, true) IS NOT DISTINCT FROM expected.fourth_key AND actual_index.indoption::text = expected.index_options; IF matched_indexes <> 3 THEN SELECT string_agg(index_relation.relname || '=' || coalesce(pg_get_indexdef(actual_index.indexrelid, 1, true), '<null>') || '|' || coalesce(pg_get_indexdef(actual_index.indexrelid, 2, true), '<null>') || '|' || coalesce(pg_get_indexdef(actual_index.indexrelid, 3, true), '<null>') || '|' || coalesce(pg_get_indexdef(actual_index.indexrelid, 4, true), '<null>'), ';' ORDER BY index_relation.relname) INTO index_evidence FROM pg_index actual_index JOIN pg_class actual_table ON actual_table.oid = actual_index.indrelid JOIN pg_namespace actual_schema ON actual_schema.oid = actual_table.relnamespace JOIN pg_class index_relation ON index_relation.oid = actual_index.indexrelid WHERE actual_schema.nspname = current_schema() AND index_relation.relname IN ('idx_sand_iam_initialization_draft_application', 'idx_sand_iam_initialization_draft_organization', 'idx_sand_iam_initialization_draft_revision_history'); RAISE EXCEPTION 'SandIAM initialization-draft index fingerprint is incompatible (matched %/3; actual %)', matched_indexes, index_evidence; END IF; END $$;

DO $$ DECLARE parent_menu_id bigint; BEGIN SELECT id INTO parent_menu_id FROM sand_system_menu WHERE code = 'SandIAMConnection' ORDER BY id LIMIT 1; IF parent_menu_id IS NULL THEN RAISE EXCEPTION 'SandIAM 0.7.0 cannot add initialization-draft permissions: parent menu SandIAMConnection is missing'; END IF; END $$;

WITH desired(code, name, sort) AS (
    VALUES
        ('sand_iam:initialization:save', '应用初始化方案新建草稿', 2027),
        ('sand_iam:initialization:update', '应用初始化方案编辑草稿', 2028),
        ('sand_iam:initialization:disable', '应用初始化方案停用草稿', 2029)
), parent AS (
    SELECT id FROM sand_system_menu WHERE code = 'SandIAMConnection' ORDER BY id LIMIT 1
), refresh_existing AS (
    UPDATE sand_system_menu existing
    SET parent_id = parent.id,
        name = desired.name,
        slug = desired.code,
        type = 3,
        path = '',
        component = '',
        icon = '',
        sort = desired.sort,
        is_hidden = 1,
        status = 1,
        update_time = CURRENT_TIMESTAMP
    FROM desired CROSS JOIN parent
    WHERE existing.code = desired.code
    RETURNING existing.id
)
INSERT INTO sand_system_menu (parent_id, name, code, slug, type, path, component, icon, sort, is_hidden, status, create_time, update_time)
SELECT parent.id, desired.name, desired.code, desired.code, 3, '', '', '', desired.sort, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM desired CROSS JOIN parent
WHERE NOT EXISTS (SELECT 1 FROM sand_system_menu existing WHERE existing.code = desired.code);

DO $$ DECLARE matched_permissions integer; BEGIN WITH desired(code, name, sort) AS ( VALUES ('sand_iam:initialization:save', '应用初始化方案新建草稿', 2027), ('sand_iam:initialization:update', '应用初始化方案编辑草稿', 2028), ('sand_iam:initialization:disable', '应用初始化方案停用草稿', 2029) ), parent AS ( SELECT id FROM sand_system_menu WHERE code = 'SandIAMConnection' ORDER BY id LIMIT 1 ) SELECT count(*) INTO matched_permissions FROM desired CROSS JOIN parent JOIN sand_system_menu actual ON actual.code = desired.code AND actual.parent_id = parent.id AND actual.name = desired.name AND actual.slug = desired.code AND actual.type = 3 AND actual.path = '' AND actual.component = '' AND actual.icon = '' AND actual.sort = desired.sort AND actual.is_hidden = 1 AND actual.status = 1; IF matched_permissions <> 3 OR EXISTS ( SELECT required.code FROM (VALUES ('sand_iam:initialization:save'), ('sand_iam:initialization:update'), ('sand_iam:initialization:disable') ) AS required(code) LEFT JOIN sand_system_menu actual ON actual.code = required.code GROUP BY required.code HAVING count(actual.id) <> 1 ) THEN RAISE EXCEPTION 'SandIAM 0.7.0 initialization-draft permission fingerprint is incompatible'; END IF; END $$;

DO $$ DECLARE recorded record; BEGIN SELECT revision, checksum, package_version INTO recorded FROM sand_iam_schema_migration WHERE migration_file = '037_initialization_draft.pgsql'; IF recorded.revision IS NOT NULL AND ( recorded.revision <> 37 OR recorded.checksum <> 'cf7013ee42f9bd6319e8c23524f274e382901af7fbb32fa947732cd8beeb640c' OR recorded.package_version <> '0.7.0' ) THEN RAISE EXCEPTION 'SandIAM migration 037 ledger identity conflicts with initialization drafts'; END IF; END $$;

WITH self_checksum(checksum) AS (VALUES ('cf7013ee42f9bd6319e8c23524f274e382901af7fbb32fa947732cd8beeb640c'))
INSERT INTO sand_iam_schema_migration (migration_file, revision, checksum, package_version, executed_time)
SELECT '037_initialization_draft.pgsql', 37, self_checksum.checksum, '0.7.0', CURRENT_TIMESTAMP
FROM self_checksum
ON CONFLICT (migration_file) DO NOTHING;

DO $$ DECLARE recorded_rows integer; BEGIN SELECT count(*) INTO recorded_rows FROM sand_iam_schema_migration WHERE migration_file = '037_initialization_draft.pgsql' AND revision = 37 AND checksum = 'cf7013ee42f9bd6319e8c23524f274e382901af7fbb32fa947732cd8beeb640c' AND package_version = '0.7.0'; IF recorded_rows <> 1 OR (SELECT count(*) FROM sand_iam_schema_migration) <> 38 THEN RAISE EXCEPTION 'SandIAM migration 037 did not close the exact 001-037 ledger'; END IF; END $$;

COMMIT;
